// Type definitions
type RGBColor = {
	r: number
	g: number
	b: number
}

type HSVColor = {
	h: number
	s: number
	v: number
}

type DragType = "saturation" | "hue" | "alpha" | null
export type SizeOptions = "28" | "32" | "36" | "40" | "44" | "48"
type ColorPickerProps = {
	onColorChange?: (hsv: number[], rgb: number[], hex: string) => void
	defaultColor?:
		| string
		| {
				h?: number
				s?: number
				v?: number
				a?: number
		  }
	size?: SizeOptions
	label?: string
	hint?: string
	hasError?: boolean
	disabled?: boolean
	inputFormat?: "HEX" | "HSL" | "OKLCH" | "HSB" | "RGBA"
	onInputFormatChange?: (format: "HEX" | "HSL" | "OKLCH" | "HSB" | "RGBA") => void
	className?: string
}

// Extend Window interface for EyeDropper API
declare global {
	interface Window {
		EyeDropper?: {
			new (): {
				open(): Promise<{ sRGBHex: string }>
			}
		}
	}
}
export const defaultInputSize = "36"
export const defaultInputRadius = "lg"

const ColorPicker: React.FC<ColorPickerProps> = ({
	size = defaultInputSize,
	onColorChange,
	defaultColor = "#007BFF",
	inputFormat: externalInputFormat = "HEX",
	onInputFormatChange,
	className,
